To achieve this in JavaScript, you can create a recursive function that traverses through each level of the object structure using dot notation (i.e., `obj.key`). If the current part of the path exists within the object, it will be added to your result array.

Here's how you could implement such a function:

```javascript
function getNestedValues(obj, searchKey) {
    const results = [];

    // Helper function to recursively traverse the object
    function traverse(obj, currentPath) {
        for (const [key, value] of Object.entries(obj)) {
            if (typeof value === 'object' && !Array.isArray(value)) {
                // Recursively call on nested objects
                traverse(value, `${currentPath}.${key}`);
            } else {
                // Check if we found the exact match
                if (searchKey === key) {
                    results.push(currentPath);
                }
            }
        }
    }

    // Start traversal from the root of the object
    traverse(obj, '');

    return results;
}

